// 문서 → 섹션(Markdown 제목) → 청크 분할
// 출력: 청크 1개당 item 1개 { content, embedText, metadata }
const cfg = $('설정').first().json;
const CHUNK_SIZE = Number(cfg.chunkSize) || 800;
const CHUNK_OVERLAP = Math.min(Number(cfg.chunkOverlap) || 0, Math.floor(CHUNK_SIZE / 2));
const BASE_DIR = String(cfg.knowledgeBaseDir).replace(/\/+$/, '');

// --- YAML front matter (key: value, key: [a, b]) 간이 파서 ---
function parseFrontMatter(text) {
  const m = text.match(/^﻿?---\r?\n([\s\S]*?)\r?\n---[ \t]*(\r?\n|$)/);
  if (!m) return { meta: {}, body: text.replace(/^﻿/, '') };
  const meta = {};
  for (const line of m[1].split(/\r?\n/)) {
    const kv = line.match(/^([A-Za-z_][\w-]*)\s*:\s*(.*)$/);
    if (!kv) continue;
    let v = kv[2].trim();
    if (/^\[.*\]$/.test(v)) {
      v = v.slice(1, -1).split(',').map((s) => s.trim().replace(/^["']|["']$/g, '')).filter(Boolean);
    } else {
      v = v.replace(/^["']|["']$/g, '');
    }
    meta[kv[1]] = v;
  }
  return { meta, body: text.slice(m[0].length) };
}

// --- Markdown 제목(#) 기준 섹션 분리. section 은 "상위 > 하위" 경로 ---
function splitSections(body) {
  const sections = [];
  const path = [];
  let buf = [];
  let inFence = false;
  const flush = () => {
    const text = buf.join('\n').trim();
    if (text) sections.push({ section: path.filter(Boolean).join(' > '), text });
    buf = [];
  };
  for (const line of body.split(/\r?\n/)) {
    if (/^\s*(```|~~~)/.test(line)) inFence = !inFence;
    const h = !inFence && line.match(/^(#{1,6})\s+(.+?)\s*#*\s*$/);
    if (h) {
      flush();
      const level = h[1].length;
      path.length = level - 1;
      path[level - 1] = h[2].trim();
      continue;
    }
    buf.push(line);
  }
  flush();
  return sections;
}

// --- 길이 제한 분할: 문단 → 문장 → 강제 절단 순으로 경계를 찾고, 앞 청크 끝부분을 겹친다 ---
function splitText(text) {
  if (text.length <= CHUNK_SIZE) return [text];
  const pieces = [];
  for (const para of text.split(/\n{2,}/)) {
    if (para.length <= CHUNK_SIZE) { pieces.push(para); continue; }
    for (const sent of para.split(/(?<=[.!?。])\s+|\n/)) {
      for (let i = 0; i < sent.length; i += CHUNK_SIZE) pieces.push(sent.slice(i, i + CHUNK_SIZE));
    }
  }
  const chunks = [];
  let cur = '';
  for (const p of pieces) {
    if (cur && cur.length + p.length + 2 > CHUNK_SIZE) {
      chunks.push(cur.trim());
      const tail = CHUNK_OVERLAP > 0 ? cur.slice(-CHUNK_OVERLAP) : '';
      cur = tail && tail.length + p.length + 2 <= CHUNK_SIZE ? tail + '\n\n' + p : p;
    } else {
      cur = cur ? cur + '\n\n' + p : p;
    }
  }
  if (cur.trim()) chunks.push(cur.trim());
  return chunks;
}

// --- 같은 상위 제목 아래 연속된 짧은 섹션은 CHUNK_SIZE 까지 묶는다 ---
// 한두 줄짜리 소제목(예: 영향 범위)이 각각 청크가 되면 LLM 에 전달되는 근거가 너무 짧아진다.
// 묶인 청크의 content 에는 [소제목] 을 남기고, section 은 "상위 > 소제목1 · 소제목2" 로 표시한다.
function packSections(sections) {
  const packs = [];
  let cur = null;
  for (const s of sections) {
    const cut = s.section.lastIndexOf(' > ');
    const parent = cut >= 0 ? s.section.slice(0, cut) : '';
    const leaf = cut >= 0 ? s.section.slice(cut + 3) : s.section;
    const block = leaf ? `[${leaf}]\n${s.text}` : s.text;
    if (cur && cur.parent === parent && cur.text.length + block.length + 2 <= CHUNK_SIZE) {
      cur.text += '\n\n' + block;
      cur.leaves.push(leaf);
    } else {
      if (cur) packs.push(cur);
      cur = { parent, leaves: [leaf], text: block, first: s };
    }
  }
  if (cur) packs.push(cur);
  return packs.map((p) => p.leaves.length === 1
    ? p.first
    : { section: [p.parent, p.leaves.filter(Boolean).join(' · ')].filter(Boolean).join(' > '), text: p.text });
}

const out = [];
for (const item of $input.all()) {
  const bin = (item.binary && item.binary.data) || {};
  const fileName = bin.fileName || item.json.fileName || 'unknown';
  const dir = String(bin.directory || '').replace(/\/+$/, '');
  const relDir = dir.startsWith(BASE_DIR) ? dir.slice(BASE_DIR.length).replace(/^\/+/, '') : dir;
  const relativePath = relDir ? `${relDir}/${fileName}` : fileName;

  const raw = String(item.json.data || '');
  const { meta, body } = parseFrontMatter(raw);
  if (!body.trim()) continue;

  const documentName = meta.documentName || fileName;
  const title = meta.title || fileName.replace(/\.[^.]+$/, '');
  const category = meta.category || relDir.split('/')[0] || 'uncategorized';
  const keywords = Array.isArray(meta.keywords) ? meta.keywords : meta.keywords ? [meta.keywords] : [];

  let index = 0;
  for (const s of packSections(splitSections(body))) {
    for (const text of splitText(s.text)) {
      const chunkId = `${relativePath}#${String(index).padStart(3, '0')}`;
      out.push({
        json: {
          content: text,
          // 임베딩에는 문서 제목·키워드·섹션을 함께 넣어 검색 정확도를 높인다 (저장되는 content 는 본문만)
          embedText: [title, keywords.join(', '), s.section, text].filter(Boolean).join('\n'),
          metadata: {
            documentName,
            docId: meta.doc_id || meta.docId || null,
            title,
            category,
            section: s.section || title,
            chunkId,
            chunkIndex: index,
            source: relativePath,
            version: meta.version || null,
            keywords,
          },
        },
      });
      index++;
    }
  }
}

// 문서가 없으면 다음 IF 노드가 실패 응답으로 보낸다 (기존 컬렉션은 건드리지 않음)
if (out.length === 0) {
  return [{ json: { noDocuments: true, knowledgeBaseDir: BASE_DIR } }];
}
return out;

// 임베딩 API 호출 횟수를 줄이기 위해 청크를 16개씩 묶는다
const BATCH_SIZE = 16;
const all = $input.all().map((i) => i.json);
const batches = [];
for (let i = 0; i < all.length; i += BATCH_SIZE) {
  batches.push({ json: { startId: i + 1, chunks: all.slice(i, i + BATCH_SIZE) } });
}
return batches;

// 임베딩 결과와 청크를 합쳐 Qdrant 포인트로 만든다.
// payload 는 n8n Qdrant Vector Store 노드 기본값(content / metadata)과 호환된다.
const batches = $('배치 구성').all();
return $input.all().map((item, b) => {
  const { startId, chunks } = batches[b].json;
  const vectors = item.json.embeddings;
  if (!Array.isArray(vectors) || vectors.length !== chunks.length) {
    throw new Error(`임베딩 개수 불일치: batch ${b}, 청크 ${chunks.length}개, 벡터 ${vectors && vectors.length}개`);
  }
  return {
    json: {
      points: chunks.map((c, i) => ({
        id: startId + i,
        vector: vectors[i],
        payload: { content: c.content, metadata: c.metadata },
      })),
    },
  };
});

const cfg = $('설정').first().json;
const chunks = $('청크 분할').all().map((i) => i.json.metadata);
const byCategory = {};
const documents = new Set();
for (const m of chunks) {
  byCategory[m.category] = (byCategory[m.category] || 0) + 1;
  documents.add(m.source);
}
const failed = $input.all().filter((i) => i.json.status !== 'ok').length;
return [{
  json: {
    success: failed === 0,
    collection: cfg.collection,
    embedModel: cfg.embedModel,
    vectorSize: $('Qdrant 포인트 구성').first().json.points[0].vector.length,
    documentCount: documents.size,
    chunkCount: chunks.length,
    chunksByCategory: byCategory,
    failedBatches: failed,
    documents: [...documents].sort(),
    startedAt: cfg.startedAt,
    finishedAt: $now.toISO(),
  },
}];
